// Fonts for the paid PDF plan (worker/lib/pdfPlanHtml.js), embedded as base64
// woff2 rather than linked. GENERATED FILE — see REGENERATE below.
//
// WHY EMBEDDED: the PDF is printed by Cloudflare Browser Rendering via
// page.setContent() (worker/routes/scanPdf.js) — there is no navigation context
// to resolve an external @font-face URL from, so a CDN link (Google Fonts or
// otherwise) would silently fall back to a system font. A document a customer
// pays 19.99 EUR for must render in the typeface it was designed in; it does not
// get to look like a fallback and pretend. Data URIs are the only mechanism that
// survives setContent, so the real font bytes travel inside the HTML string.
//
// PROVENANCE: verbatim bytes of two npm packages that were ALREADY in
// package.json before this file existed — @fontsource-variable/geist and
// @fontsource-variable/jetbrains-mono (both SIL OFL-1.1; the LICENSE files ship
// inside those packages). These are variable fonts: one file carries the whole
// weight axis, so 400/500/600 — the three weights the design actually uses —
// all come out of these four files, with no per-weight duplicates.
//
// SUBSETS: Latin + Latin-Extended only. The Cyrillic/Greek/Vietnamese subsets
// are ~60KB of glyphs this document never sets (its content is EU-market URLs,
// WCAG criterion titles, CSS selectors and captured HTML). A character outside
// these ranges falls back to a system font — visibly different, not silently
// wrong, which is the failure mode we want.
//
// REGENERATE after a font package upgrade: base64-encode these four files, in
// this order, into the four constants below —
//   @fontsource-variable/geist/files/geist-latin-wght-normal.woff2
//   @fontsource-variable/geist/files/geist-latin-ext-wght-normal.woff2
//   @fontsource-variable/jetbrains-mono/files/jetbrains-mono-latin-wght-normal.woff2
//   @fontsource-variable/jetbrains-mono/files/jetbrains-mono-latin-ext-wght-normal.woff2
// and re-copy the unicode-range strings from those packages' own wght.css.

export const GEIST_LATIN_B64 = ''

export const GEIST_LATIN_EXT_B64 = ''

export const MONO_LATIN_B64 = ''

export const MONO_LATIN_EXT_B64 = ''

// Copied verbatim from the two packages' own wght.css — not hand-narrowed.
export const LATIN_RANGE =
  'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD'

export const LATIN_EXT_RANGE =
  'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF'

// One @font-face per family per subset. `font-weight: 100 900` is what makes
// Chromium treat the file as variable and cut a real 500/600 off the weight
// axis, instead of faux-bolding one static master.
export const FONT_FACE_CSS = `
  @font-face {
    font-family: "Geist";
    font-style: normal;
    font-weight: 100 900;
    src: url(data:font/woff2;base64,${GEIST_LATIN_B64}) format("woff2");
    unicode-range: ${LATIN_RANGE};
  }
  @font-face {
    font-family: "Geist";
    font-style: normal;
    font-weight: 100 900;
    src: url(data:font/woff2;base64,${GEIST_LATIN_EXT_B64}) format("woff2");
    unicode-range: ${LATIN_EXT_RANGE};
  }
  @font-face {
    font-family: "JetBrains Mono";
    font-style: normal;
    font-weight: 100 800;
    src: url(data:font/woff2;base64,${MONO_LATIN_B64}) format("woff2");
    unicode-range: ${LATIN_RANGE};
  }
  @font-face {
    font-family: "JetBrains Mono";
    font-style: normal;
    font-weight: 100 800;
    src: url(data:font/woff2;base64,${MONO_LATIN_EXT_B64}) format("woff2");
    unicode-range: ${LATIN_EXT_RANGE};
  }
`
